(()=>{
'use strict';
const {Game,dropRoom,position,LIMIT}=SleepGame,game=new Game(),colors=['#ffab91','#a5d7ff','#d4f179','#f4b8e8'];
const section=document.createElement('section');section.id='game';section.className='game hidden';section.setAttribute('aria-label','Gra: kto znowu łazi');
section.innerHTML=`<div class="game-head"><div><span class="game-eyebrow">ziemniak na dyżurze</span><h2>kto znowu łazi?!</h2></div><button class="game-close" aria-label="Zamknij grę">×</button></div><p class="game-instructions"><b>Przeciągaj uczestników do numeru na piżamie.</b> Tych za szybą złap dopiero w pokoju. Wytrzymaj 60 sekund. Pięć osób w cudzych pokojach = koniec dyżuru.</p><div class="game-stats"><span><small>do końca</small><b id="gameTime">60 s</b></span><span><small>punkty</small><b id="gameScore">0</b></span><span><small>seria</small><b id="gameCombo">—</b></span><span><small>tempo</small><b id="gameLevel">1 / 3</b></span></div><div class="chaos" id="chaos"><span id="gameWrong">0 / 5 nie u siebie</span><div class="chaos-pips" aria-hidden="true">${'<i></i>'.repeat(5)}</div><strong id="chaosHint">jeszcze cisza</strong></div><div class="board" id="board"><div class="window-lane"><span id="windowHint">ZA SZYBĄ · tu nie sięgniesz · łap po wejściu do pokoju</span></div><div class="hall-label">KORYTARZ · tutaj złapiesz każdego ↓</div><div id="gameOverlay" class="game-overlay"><div><span id="overlayIcon" aria-hidden="true">☾</span><h3 id="overlayTitle">ogarniesz tę wycieczkę?</h3><p id="overlayText">Numer na piżamie = właściwy pokój. Później niektórzy pójdą za szybą — tych złapiesz dopiero po wejściu do środka. Najpierw jedna próba.</p><button id="overlayAction">dawaj, pokaż</button></div></div></div><div class="game-message" id="gameMessage" role="status">W pokojach i na korytarzu złapiesz każdego. Za szybą — dopiero gdy wejdzie do środka.</div><div class="game-controls"><button id="gamePause" class="hidden">pauza</button><button id="gameRestart" class="hidden">od nowa</button><small id="gameBest"></small></div><p class="game-keyboard">Klawiatura: Tab wybiera osobę, Spacja ją chwyta, 1–4 odkłada do pokoju. Esc puszcza.</p>`;
document.querySelector('main').append(section);const launch=document.createElement('button');launch.className='bigbtn';launch.id='playGame';launch.textContent='ktoś łazi po korytarzu 👀';document.querySelector('.buttons').append(launch);
const by=id=>section.querySelector('#'+id),board=by('board'),overlay=by('gameOverlay'),rooms=[],actors=new Map();let drag=null,last=0,raf=0,best=0,lastLevel=1,boardWidth=0;
try{best=Number(localStorage.getItem('sleepGameBestV2'))||0}catch{}
by('gameBest').textContent='rekord: '+best+' pkt';
for(let i=0;i<4;i++){const room=document.createElement('div');room.className='room';room.dataset.room=i;room.style.setProperty('--room',colors[i]);room.style.left=(i*25)+'%';room.innerHTML=`<div class="room-title"><b>${i+1}</b><span>pokój ${i+1}</span></div><span class="room-target">tutaj ↓</span><span class="room-warning">ktoś się wymyka…</span>`;room.setAttribute('aria-label','Pokój '+(i+1));board.append(room);rooms.push(room)}
function say(text){by('gameMessage').textContent=text}
function sound(name){NightSounds.play(name)}
function rects(){return rooms.map(r=>r.getBoundingClientRect())}
function clearTargets(){rooms.forEach(r=>r.classList.remove('target','over','bad-drop'))}
function cleanDrag(){const old=drag;drag=null;clearTargets();if(old){old.el.classList.remove('dragging');old.el.setAttribute('aria-pressed','false');if(old.pointerId!==null&&old.el.hasPointerCapture(old.pointerId))old.el.releasePointerCapture(old.pointerId)}}
function cancelDrag(){game.cancel();cleanDrag();render()}
function actorCentre(){const r=drag.el.getBoundingClientRect();return {x:r.left+r.width/2,y:r.top+r.height/2}}
function move(e){if(!drag||e.pointerId!==drag.pointerId)return;e.preventDefault();const r=board.getBoundingClientRect();drag.x=e.clientX-drag.offsetX;drag.y=e.clientY-drag.offsetY;drag.moved ||= Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>3;drag.el.style.left=(drag.x-r.left-board.clientLeft)+'px';drag.el.style.top=(drag.y-r.top-board.clientTop)+'px';const hit=dropRoom({x:e.clientX,y:e.clientY},actorCentre(),rects(),drag.p.home);rooms.forEach((room,i)=>room.classList.toggle('over',i===hit&&i===drag.p.home))}
function release(room){if(!drag)return;const p=drag.p,result=game.release(room);cleanDrag();if(result.ok){sound('win');rooms[p.home].classList.add('delivered');setTimeout(()=>rooms[p.home].classList.remove('delivered'),450);if(result.practice){say('o, właśnie tak! teraz 60 sekund. łap ich zanim wejdą do cudzych.');lastLevel=1}else{say(`+${result.points} · do własnego łóżka!${result.multiplier>1?' seria ×'+result.multiplier:''}`);const tag=document.createElement('span');tag.className='score-pop';tag.textContent='+'+result.points;tag.style.left=((p.home+.5)*25)+'%';board.append(tag);setTimeout(()=>tag.remove(),650)}}else if(result.reason!=='inactive'){sound('no');say(result.reason==='outside'?`za daleko od drzwi. odstaw do pokoju ${p.home+1}.`:`to nie jego pokój — na piżamie ma ${p.home+1}.`);if(room!==null){rooms[room].classList.add('bad-drop');setTimeout(()=>rooms[room].classList.remove('bad-drop'),500)}}render()}
function pointerUp(e){if(!drag||drag.pointerId!==e.pointerId)return;e.preventDefault();move(e);if(!drag.moved){cancelDrag();say('przytrzymaj i przeciągnij. sam klik go nie odprowadza.');return}release(dropRoom({x:e.clientX,y:e.clientY},actorCentre(),rects(),drag.p.home))}
function begin(p,el,e){if(p.state==='window'){say('ten jest za szybą. złapiesz go, gdy wejdzie do pokoju.');return}if(drag||!game.pickup(p.id))return;e?.preventDefault();const r=el.getBoundingClientRect();drag={p,el,pointerId:e?e.pointerId:null,startX:e?.clientX,startY:e?.clientY,offsetX:e?e.clientX-(r.left+r.width/2):0,offsetY:e?e.clientY-(r.top+r.height/2):0,x:r.left+r.width/2,y:r.top+r.height/2,moved:false};el.classList.add('dragging');el.setAttribute('aria-pressed','true');rooms[p.home].classList.add('target');say(`pokój ${p.home+1} podświetlony. tam go odłóż.`);if(e)el.setPointerCapture(e.pointerId)}
function createActor(p){const el=document.createElement('button');el.type='button';el.className='person';el.style.setProperty('--person',colors[p.home]);el.innerHTML=`<span class="face" aria-hidden="true">•ᴗ•</span><b>${p.home+1}</b><span class="person-status"></span>`;el.dataset.id=p.id;el.setAttribute('aria-pressed','false');el.onpointerdown=e=>{if(e.button===0&&e.isPrimary)begin(p,el,e)};el.onpointermove=move;el.onpointerup=pointerUp;el.onpointercancel=e=>{if(drag?.pointerId===e.pointerId){cancelDrag();say('chwyt przerwany. możesz złapać go ponownie.')}};el.onlostpointercapture=e=>{if(drag?.pointerId===e.pointerId)cancelDrag()};el.ondragstart=e=>e.preventDefault();el.onkeydown=e=>{if([' ','Enter'].includes(e.key)){e.preventDefault();if(drag?.p.id===p.id)cancelDrag();else begin(p,el,null)}};el.onclick=e=>{e.preventDefault()};board.append(el);actors.set(p.id,el);return el}
function showOverlay(title,text,label,icon='☾'){overlay.classList.remove('hidden');by('overlayTitle').textContent=title;by('overlayText').textContent=text;by('overlayAction').textContent=label;by('overlayIcon').textContent=icon}
function render(){boardWidth=board.clientWidth;const active=new Set(game.people.map(p=>p.id));for(const [id,el] of actors)if(!active.has(id)){el.remove();actors.delete(id)}
for(const p of game.people){const el=actors.get(p.id)||createActor(p);el.classList.toggle('wrong',p.state==='wrong');el.classList.toggle('walking',p.state==='walking');el.classList.toggle('window-person',p.state==='window');el.querySelector('.person-status').textContent=p.state==='wrong'?'!':p.state==='window'?'×':'→';el.setAttribute('aria-label',`Uczestnik ${p.id}, dom: pokój ${p.home+1}, ${p.state==='wrong'?'w złym pokoju '+(p.target+1):p.state==='window'?'za szybą, poza zasięgiem':'na korytarzu'}`);el.disabled=!['playing','practice'].includes(game.mode);el.setAttribute('aria-disabled',String(el.disabled||p.state==='window'));if(drag?.p.id!==p.id){const pos=position(p,boardWidth);el.style.left=pos.x+'px';el.style.top=pos.y+'px'}}
rooms.forEach((r,i)=>{r.classList.toggle('leaving',game.pending?.home===i);r.querySelector('.room-warning').textContent=game.pending?.windowRoute?'psst… oknem!':'ktoś się wymyka…'});board.classList.toggle('window-active',game.people.some(p=>p.state==='window'));by('windowHint').textContent=game.people.some(p=>p.state==='window')?'ZA SZYBĄ · nie złapiesz! poczekaj, aż wejdzie do pokoju':'ZA SZYBĄ · tu nie sięgniesz · łap po wejściu do pokoju';by('gameTime').textContent=game.mode==='practice'?'próba':Math.ceil(60-game.elapsed)+' s';by('gameScore').textContent=game.score;by('gameCombo').textContent=game.combo>=3?'×'+(game.combo>=6?3:2):game.combo?game.combo+' / 3':'—';by('gameLevel').textContent=game.level+' / 3';by('gameWrong').textContent=game.wrong+' / '+LIMIT+' nie u siebie';by('chaos').classList.toggle('danger',game.wrong>=4);by('chaos').querySelectorAll('i').forEach((p,i)=>p.classList.toggle('filled',i<game.wrong));by('chaosHint').textContent=game.wrong>=5?'limit przekroczony — koniec dyżuru':game.wrong>=4?'jeszcze jedna osoba i po nas!':game.wrong>=2?'robi się impreza':game.wrong?'ktoś pomylił łóżko':'jeszcze cisza';
by('gamePause').classList.toggle('hidden',!['playing','practice','paused'].includes(game.mode));by('gamePause').textContent=game.mode==='paused'?'wracamy':'pauza';by('gameRestart').classList.toggle('hidden',game.mode==='ready');}
function ended(){cleanDrag();sound(game.endReason==='won'?'sleep':'no');if(game.score>best){best=game.score;try{localStorage.setItem('sleepGameBestV2',String(best))}catch{}by('gameBest').textContent='rekord: '+best+' pkt'}showOverlay(game.endReason==='won'?'dyżur ogarnięty.':'no i obudzili wszystkich.',game.endReason==='won'?`${game.score} pkt · ${game.saved} osób odstawionych. Ziemniak może wreszcie spać.`:`5 osób w cudzych pokojach. Koniec dyżuru po ${Math.floor(game.elapsed)} s. Wynik: ${game.score} pkt. Następnym razem ratuj najpierw tych z wykrzyknikiem.`,'jeszcze jedna nocka',game.endReason==='won'?'☾':'!');say(game.endReason==='won'?'wygrana! pełna minuta bez katastrofy.':'przegrana: limit 5 osób w złych pokojach.');render();by('overlayAction').focus({preventScroll:true})}
function frame(time){let dt=last?Math.max(0,(time-last)/1000):0;last=time;const was=game.mode;while(dt>0&&game.mode==='playing'){const slice=Math.min(dt,.1);game.step(slice);dt-=slice;}for(const event of game.events.splice(0)){if(event.type==='arrival'){sound('no');if(!drag)say('w cudzym pokoju! wykrzyknik pokazuje, kogo ratować.')}}if(game.level!==lastLevel){lastLevel=game.level;sound('popup');if(!drag)say(lastLevel===2?'tempo 2 z 3. uwaga: teraz mogą chodzić też za oknami.':'ostatnie 20 sekund. teraz wszyscy chcą pogadać.')}if(was==='playing'&&game.mode==='ended')ended();else render();raf=requestAnimationFrame(frame)}
function start(practice=false){cleanDrag();practice?game.practice():game.start();last=performance.now();lastLevel=1;overlay.classList.add('hidden');say(practice?'próba bez presji: przeciągnij dwójkę z pokoju 4 do pokoju 2.':'dyżur rusza. łap ich zanim zrobią imprezę.');render()}
function pause(){if(game.mode==='paused'){game.resume();last=performance.now();overlay.classList.add('hidden');say('dobra, pilnujemy dalej.')}else{cancelDrag();game.pause();if(game.mode==='paused')showOverlay('chwila oddechu.','Zegar i uczestnicy stoją. Po wznowieniu łap tych w środku. Za szybą nadal będą poza zasięgiem.','wracamy','Ⅱ')}render()}
by('overlayAction').onclick=()=>{if(game.mode==='paused')pause();else start(game.mode==='ready')};by('gamePause').onclick=pause;by('gameRestart').onclick=()=>start(false);
section.addEventListener('keydown',e=>{if(!drag)return;if(e.key==='Escape'){e.preventDefault();cancelDrag();say('puszczony. łap dalej.')}else if(drag.pointerId===null&&/^[1-4]$/.test(e.key)){e.preventDefault();release(Number(e.key)-1)}});
launch.onclick=()=>{quiet();section.classList.remove('hidden');render();last=performance.now();if(!raf)raf=requestAnimationFrame(frame);section.scrollIntoView({behavior:'smooth',block:'start'})};section.querySelector('.game-close').onclick=()=>{if(['playing','practice'].includes(game.mode))pause();cancelAnimationFrame(raf);raf=0;section.classList.add('hidden');launch.focus()};document.addEventListener('visibilitychange',()=>{if(document.hidden&&['playing','practice'].includes(game.mode))pause()});window.addEventListener('blur',()=>{if(['playing','practice'].includes(game.mode))pause()});new ResizeObserver(()=>{if(drag)cancelDrag();render()}).observe(board);
render();
})();
